namespace ET.Server
{
    [MessageHandler(SceneType.Player)] public class G2P_EnterWorldHandler: MessageHandler<OnlinePlayerActor, G2P_EnterWorld, P2G_EnterWorld> { protected override async ETTask Run(OnlinePlayerActor actor, G2P_EnterWorld request, P2G_EnterWorld response) { var r=await actor.EnterWorld(request.SessionEpoch,request.OperationId,request.MapId); response.Error=r.Error;response.Message=r.Message;response.HasWorld=r.HasWorld;response.World=r.World; } }
    [MessageHandler(SceneType.Player)] public class G2P_GetCurrentWorldHandler: MessageHandler<OnlinePlayerActor, G2P_GetCurrentWorld, P2G_GetCurrentWorld> { protected override async ETTask Run(OnlinePlayerActor actor, G2P_GetCurrentWorld request, P2G_GetCurrentWorld response) { var r=await actor.GetCurrentWorld(request.SessionEpoch);response.Error=r.Error;response.Message=r.Message;response.HasWorld=r.HasWorld;response.World=r.World; } }
    [MessageHandler(SceneType.Player)] public class G2P_LeaveWorldHandler: MessageHandler<OnlinePlayerActor, G2P_LeaveWorld, P2G_LeaveWorld> { protected override async ETTask Run(OnlinePlayerActor actor,G2P_LeaveWorld request,P2G_LeaveWorld response){var r=await actor.LeaveWorld(request.SessionEpoch,request.OperationId);response.Error=r.Error;response.Message=r.Message;} }
    [MessageHandler(SceneType.Player)] public class G2P_ReportWorldTransformHandler: MessageHandler<OnlinePlayerActor,G2P_ReportWorldTransform,P2G_ReportWorldTransform>{protected override async ETTask Run(OnlinePlayerActor actor,G2P_ReportWorldTransform request,P2G_ReportWorldTransform response){var r=await actor.ReportWorldTransform(request.SessionEpoch,request.PositionX,request.PositionY,request.PositionZ,request.YawDegrees,request.LifecycleRevision);response.Error=r.Error;response.Message=r.Message;response.WorldId=r.WorldId;response.MapId=r.MapId;response.UnitId=r.UnitId;response.StateRevision=r.StateRevision;response.LifecycleRevision=r.LifecycleRevision;} }
    [MessageHandler(SceneType.Player)] public class G2P_WorldMeleeAttackHandler:MessageHandler<OnlinePlayerActor,G2P_WorldMeleeAttack,P2G_WorldMeleeAttack>{protected override async ETTask Run(OnlinePlayerActor a,G2P_WorldMeleeAttack q,P2G_WorldMeleeAttack p){var r=await a.WorldMeleeAttack(q.SessionEpoch,q.AttackSequence,q.WeaponItemId,q.AimX,q.AimZ,q.LifecycleRevision,q.AimY,q.OriginX,q.OriginY,q.OriginZ,q.HasProjectileOrigin,q.CollisionContentHash);p.Error=r.Error;p.Message=r.Message;p.WorldId=r.WorldId;p.UnitId=r.UnitId;p.AttackSequence=r.AttackSequence;p.Accepted=r.Accepted;p.WorldRevision=r.WorldRevision;p.LifecycleRevision=r.LifecycleRevision;}}
    [MessageHandler(SceneType.Player)] public class G2P_ReportWorldEnemyNavigationHandler:MessageHandler<OnlinePlayerActor,G2P_ReportWorldEnemyNavigation,P2G_ReportWorldEnemyNavigation>{protected override async ETTask Run(OnlinePlayerActor a,G2P_ReportWorldEnemyNavigation q,P2G_ReportWorldEnemyNavigation p){var r=await a.ReportWorldEnemyNavigation(q.SessionEpoch,q.NavigationLeaseRevision,q.ReportSequence,q.Reports);p.Error=r.Error;p.Message=r.Message;p.Accepted=r.Accepted;p.CurrentLeaseRevision=r.LeaseRevision;p.LastAcceptedReportSequence=r.LastSequence;p.WorldRevision=r.WorldRevision;}}
    [MessageHandler(SceneType.Player)] public class G2P_OpenWorldCorpseHandler:MessageHandler<OnlinePlayerActor,G2P_OpenWorldCorpse,P2G_OpenWorldCorpse>{protected override async ETTask Run(OnlinePlayerActor a,G2P_OpenWorldCorpse q,P2G_OpenWorldCorpse p){var r=await a.OpenWorldCorpse(q.SessionEpoch,q.CorpseId,q.LifecycleRevision);p.Error=r.Error;p.Message=r.Message;p.HasCorpse=r.Corpse!=null;p.CorpseContents=r.Corpse;p.SelfInventory=r.Inventory;}}
    [MessageHandler(SceneType.Player)] public class G2P_OperateWorldInventoryHandler:MessageHandler<OnlinePlayerActor,G2P_OperateWorldInventory,P2G_OperateWorldInventory>{protected override async ETTask Run(OnlinePlayerActor a,G2P_OperateWorldInventory q,P2G_OperateWorldInventory p){var r=await a.OperateWorldInventory(q);p.Error=r.Error;p.Message=r.Message;p.Accepted=r.Accepted;p.SelfInventory=r.Inventory;p.HasCorpse=r.HasCorpse;p.CorpseContents=r.Corpse;}}
    [MessageHandler(SceneType.Player)] public class G2P_OperateWorldTemporaryBuildingHandler:MessageHandler<OnlinePlayerActor,G2P_OperateWorldTemporaryBuilding,P2G_OperateWorldTemporaryBuilding>{protected override async ETTask Run(OnlinePlayerActor a,G2P_OperateWorldTemporaryBuilding q,P2G_OperateWorldTemporaryBuilding p){var r=await a.OperateWorldTemporaryBuilding(q);p.Error=r.Error;p.Message=r.Message;p.Accepted=r.Accepted;p.WorldRevision=r.WorldRevision;p.HasBuilding=r.Building!=null;p.Building=r.Building;p.RemovedRuntimeId=r.RemovedRuntimeId;p.SelfInventory=r.Inventory;p.ServerTime=r.ServerTime;}}
}
